param()
$ErrorActionPreference="Stop";$runDir="C:\Users\aaron\Desktop\URAP\artifacts\detached_ard100_vatd_baseline_v1";$meta=Get-Content (Join-Path $runDir "meta.json") -Raw|ConvertFrom-Json;$progressPath=Join-Path $runDir "progress.json";$progress=if(Test-Path $progressPath){Get-Content $progressPath -Raw|ConvertFrom-Json}else{[pscustomobject]@{stage="starting";done=0;total=6}};$all=@(Get-CimInstance Win32_Process);$ids=New-Object System.Collections.Generic.HashSet[int];[void]$ids.Add([int]$meta.pid);do{$before=$ids.Count;foreach($proc in $all){if($ids.Contains([int]$proc.ParentProcessId)){[void]$ids.Add([int]$proc.ProcessId)}}}while($ids.Count -gt $before);$matching=@($all|Where-Object {$ids.Contains([int]$_.ProcessId)});$alive=$matching.Count -gt 0;$last=if(Test-Path $progressPath){(Get-Item $progressPath).LastWriteTime.ToString("o")}elseif(Test-Path $meta.stdout_log){(Get-Item $meta.stdout_log).LastWriteTime.ToString("o")}else{$null};$gpuRows=@(& nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader 2>$null);$pids=@($matching|Select-Object -ExpandProperty ProcessId -Unique);$gpu=@($gpuRows|Where-Object {$row=$_;$pids|Where-Object {$row -match "^$($_),"}});[pscustomobject]@{status=if($alive){"RUNNING"}else{"NOT RUNNING"};done=[int]$progress.done;total=[int]$progress.total;stage=$progress.stage;launcher_pid=[int]$meta.pid;process_pids=$pids;start_time=$meta.start_time;last_output_timestamp=$last;last_completed_unit=$progress.stage;stdout_log=$meta.stdout_log;stderr_log=$meta.stderr_log;progress_json=$progressPath;gpu_process_signal=($gpu -join "; ")}|ConvertTo-Json -Depth 3
